package com.example.order;

public class OrderService {
    private final OrderRepository orderRepository;
    private final InventoryReservationService inventoryReservationService;
    private final PaymentIntentService paymentIntentService;
    private final OrderEventPublisher eventPublisher;
    private final FulfillmentPolicy fulfillmentPolicy;

    public OrderService(OrderRepository orderRepository,
                        InventoryReservationService inventoryReservationService,
                        PaymentIntentService paymentIntentService,
                        OrderEventPublisher eventPublisher,
                        FulfillmentPolicy fulfillmentPolicy) {
        this.orderRepository = orderRepository;
        this.inventoryReservationService = inventoryReservationService;
        this.paymentIntentService = paymentIntentService;
        this.eventPublisher = eventPublisher;
        this.fulfillmentPolicy = fulfillmentPolicy;
    }

    @Transactional
    public Order createOrder(Order order) {
        inventoryReservationService.reserveFor(order);
        paymentIntentService.createIntent(order);
        order.markReady();
        orderRepository.save(order);
        if (fulfillmentPolicy.shouldPublishOrderCreated(order)) {
            eventPublisher.publish("ORDER_CREATED", order.getId());
        }
        return order;
    }
}

